import { ok, fail } from './result.js';
import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
import { getProduct } from './catalogue.js';
import { roundCents } from './money.js';
import { nextInvoiceNumber } from './numbering.js';
import { isValidDate, addDays } from './dates.js';

/**
 * Validate a discount percentage.
 * @param {unknown} discountPercent
 * @returns {boolean}
 */
function isValidDiscount(discountPercent) {
  if (typeof discountPercent !== 'number') return false;
  return discountPercent >= 0 && discountPercent <= 100;
}

/**
 * Calculate due date based on payment terms.
 * @param {string} issueDate
 * @param {string} terms
 * @returns {string}
 */
function calculateDueDate(issueDate, terms) {
  if (terms === 'NET14') {
    return addDays(issueDate, 14);
  } else if (terms === 'NET30') {
    return addDays(issueDate, 30);
  } else if (terms === 'EOM') {
    const [year, month] = issueDate.split('-').map(Number);
    // Last day of the month
    const lastDay = new Date(Date.UTC(year, month, 0)).getUTCDate();
    return `${year}-${String(month).padStart(2, '0')}-${String(lastDay).padStart(2, '0')}`;
  }
  return null;
}

/**
 * Create a draft invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number, discountPercent?: number }>, terms?: string }}
 * @returns {import('./result.js').Result<{ customerId: string, issueDate: string, status: 'draft', terms: string, dueDate: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number, discountPercent: number }> }>}
 */
export function createInvoice({ customerId, issueDate, lines, terms = 'NET30' }) {
  // Normalize and validate customer
  const normalizedCustomerId = normalizeId(customerId);
  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) return customerResult;
  const customer = customerResult.value;

  // Validate date
  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  // Validate and calculate due date
  if (!['NET14', 'NET30', 'EOM'].includes(terms)) {
    return fail('TERMS_INVALID');
  }
  const dueDate = calculateDueDate(issueDate, terms);

  // Validate lines
  if (!lines || lines.length === 0) return fail('NO_LINES');

  // Process each line
  const processedLines = [];
  for (const line of lines) {
    // Validate qty
    if (!Number.isInteger(line.qty) || line.qty <= 0) {
      return fail('QTY_INVALID');
    }

    // Determine discount: explicit value wins, otherwise use tier discount
    const discountPercent = line.discountPercent !== undefined ? line.discountPercent : TIER_DISCOUNTS[customer.tier];
    if (!isValidDiscount(discountPercent)) {
      return fail('DISCOUNT_INVALID');
    }

    // Validate SKU and get product details
    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    processedLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent,
    });
  }

  return ok({
    customerId: normalizedCustomerId,
    issueDate,
    status: 'draft',
    terms,
    dueDate,
    lines: processedLines,
  });
}

/**
 * Calculate the total for a single line.
 * @param {{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number }} line
 * @returns {number} Total in cents
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate totals for an invoice.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number, discountPercent: number }>, voucher?: { code: string, amount: number } }} invoice
 * @returns {{ subtotal: number, discount: number, vat: number, voucher: number, total: number }}
 */
export function invoiceTotals(invoice) {
  let subtotal = 0;
  let discount = 0;
  let vat = 0;

  for (const line of invoice.lines) {
    const lineAmount = lineTotal(line);
    const lineDiscount = roundCents(lineAmount * line.discountPercent / 100);
    const lineAfterDiscount = lineAmount - lineDiscount;
    const lineVAT = roundCents(lineAfterDiscount * line.vatRate / 100);

    subtotal += lineAmount;
    discount += lineDiscount;
    vat += lineVAT;
  }

  const voucherAmount = invoice.voucher?.amount ?? 0;
  const total = Math.max(0, subtotal - discount + vat - voucherAmount);

  return { subtotal, discount, vat, voucher: voucherAmount, total };
}

/**
 * Add or update a line on a draft invoice.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number, discountPercent: number }> }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} lineData
 * @returns {import('./result.js').Result<{ customerId: string, issueDate: string, status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number, discountPercent: number }> }>}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  if (!Number.isInteger(qty) || qty <= 0) {
    return fail('QTY_INVALID');
  }

  // Get customer for tier discount
  const customerResult = getCustomer(invoice.customerId);
  if (!customerResult.ok) return customerResult;
  const customer = customerResult.value;

  // Determine discount: explicit value wins, otherwise use tier discount
  const discount = discountPercent !== undefined ? discountPercent : TIER_DISCOUNTS[customer.tier];
  if (!isValidDiscount(discount)) {
    return fail('DISCOUNT_INVALID');
  }

  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  const product = productResult.value;
  const newLines = invoice.lines.map((line) => ({ ...line }));
  const existingLineIndex = newLines.findIndex((line) => line.sku === sku);

  if (existingLineIndex >= 0) {
    newLines[existingLineIndex].qty += qty;
  } else {
    newLines.push({
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent: discount,
    });
  }

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: invoice.status,
    lines: newLines,
  });
}

/**
 * Remove a line from a draft invoice.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number, discountPercent: number }> }} invoice
 * @param {string} sku
 * @returns {import('./result.js').Result<{ customerId: string, issueDate: string, status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number, discountPercent: number }> }>}
 */
export function removeLine(invoice, sku) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex < 0) return fail('LINE_NOT_FOUND');

  if (invoice.lines.length === 1) return fail('NO_LINES');

  const newLines = invoice.lines.filter((line) => line.sku !== sku);

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: invoice.status,
    lines: newLines,
  });
}

/**
 * Issue a draft invoice, assigning it an invoice number and marking it as issued.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number, discountPercent: number }> }} invoice
 * @param {Array<string>} existingNumbers - Invoice numbers already in use
 * @returns {import('./result.js').Result<{ customerId: string, issueDate: string, status: string, number: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number, discountPercent: number }> }>}
 */
export function issueInvoice(invoice, existingNumbers) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: 'issued',
    number,
    terms: invoice.terms,
    dueDate: invoice.dueDate,
    lines: invoice.lines.map((line) => ({ ...line })),
  });
}

/**
 * Apply a voucher to a draft invoice.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array, voucher?: { code: string, amount: number } }} invoice
 * @param {{ code: string, amount: number }} voucher
 * @returns {import('./result.js').Result<{ customerId: string, issueDate: string, status: string, lines: Array, voucher: { code: string, amount: number } }>}
 */
export function applyVoucher(invoice, { code, amount }) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  if (invoice.voucher) return fail('VOUCHER_EXISTS');

  if (!Number.isInteger(amount) || amount <= 0) {
    return fail('AMOUNT_INVALID');
  }

  return ok({
    ...invoice,
    voucher: { code, amount },
  });
}

